/**
 * build 前跑：抓 SEC company_tickers.json，取前 500 大（該檔已依市值排序），
 * 寫入 web/.static-tickers.json 供 nuxt.config prerender 與 sitemap 使用。
 *
 *   npx tsx scripts/generate-static.ts
 *
 * GitHub Actions 每週跑一次後 nuxt generate 重新產出靜態頁。
 */
import { writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const UA = process.env.SEC_USER_AGENT
if (!UA) {
  console.error('SEC_USER_AGENT 未設定')
  process.exit(1)
}

const res = await fetch('https://www.sec.gov/files/company_tickers.json', {
  headers: { 'User-Agent': UA },
})
if (!res.ok) {
  console.error(`SEC ${res.status}`)
  process.exit(1)
}
const raw = (await res.json()) as Record<string, { ticker: string }>
const tickers = Object.values(raw)
  .slice(0, 500)
  .map((r) => r.ticker.toUpperCase())

const out = resolve(import.meta.dirname, '..', '.static-tickers.json')
writeFileSync(out, JSON.stringify(tickers, null, 2))
console.log(`寫入 ${tickers.length} 檔 → ${out}`)

import { defineEventHandler, getQuery, createError } from 'h3'
import { resolveTicker } from '../utils/cik'
import { getFilings } from '../utils/filings'
import { parseTickers, parseRange } from '../utils/params'

/**
 * GET /api/filings?ticker=AAPL&years=5&forms=10-K,10-Q
 * GET /api/filings?ticker=AAPL&from=2021Q1&to=2026Q2
 * → { results: [{ company, cik, isForeignIssuer, filings: [...] }] }
 */
export default defineEventHandler(async (event) => {
  const query = getQuery(event)
  const tickers = parseTickers(query.ticker)
  const range = parseRange(query as Record<string, unknown>)
  const forms = query.forms
    ? String(query.forms).split(',').map((f) => f.trim()).filter(Boolean)
    : undefined

  const results = []
  for (const t of tickers) {
    const ref = await resolveTicker(t)
    if (!ref) {
      // Edge case 8：明確錯誤訊息，不回空陣列
      throw createError({
        statusCode: 404,
        statusMessage: 'Not Found',
        message: `找不到「${t}」。請確認 ticker 拼寫；已下市公司與多數 ETF 不在 SEC 申報名單內。`,
      })
    }
    const r = await getFilings(ref, range.fromDate, range.toDate, forms)
    // 以會計季別精準過濾（日期界線因錯開的會計年度刻意放寬）；年報視為 Q4
    const lo = range.fromFy * 4 + range.fromQ
    const hi = range.toFy * 4 + range.toQ
    r.filings = r.filings.filter((f) => {
      const m = f.fiscalPeriod.match(/^FY(\d{4})(?: Q([1-4]))?$/)
      if (!m) return true // 無法解析（如 6-K 無季別）時保留
      const idx = Number(m[1]) * 4 + (m[2] ? Number(m[2]) : 4)
      return idx >= lo && idx <= hi
    })
    results.push(r)
  }
  return tickers.length === 1 ? results[0] : { results }
})

import { defineEventHandler, getQuery, createError } from 'h3'
import { resolveTicker } from '../utils/cik'
import { getFinancials } from '../utils/financials'
import { parseTickers, parseRange, clampPeriods } from '../utils/params'

/**
 * GET /api/financials?ticker=AAPL&years=5
 * GET /api/financials?ticker=AAPL&from=2021Q1&to=2026Q2
 * → { company, cik, mapVersion, periods, lineItems, derived }
 */
export default defineEventHandler(async (event) => {
  const query = getQuery(event)
  const tickers = parseTickers(query.ticker)
  const range = parseRange(query as Record<string, unknown>)

  const results = []
  for (const t of tickers) {
    const ref = await resolveTicker(t)
    if (!ref) {
      throw createError({
        statusCode: 404,
        statusMessage: 'Not Found',
        message: `找不到「${t}」。請確認 ticker 拼寫；已下市公司與多數 ETF 不在 SEC 申報名單內。`,
      })
    }
    const fin = clampPeriods(await getFinancials(ref, range.fromFy, range.toFy), range)
    results.push(fin)
  }
  return tickers.length === 1 ? results[0] : { results }
})

import { defineEventHandler, getQuery, setHeader, createError } from 'h3'
import { resolveTicker } from '../../utils/cik'
import { getFinancials } from '../../utils/financials'
import { parseTickers, parseRange, clampPeriods } from '../../utils/params'

/**
 * GET /api/financials/csv?ticker=AAPL&from=2021Q1&to=2026Q2&statement=IS
 * → text/csv（單一報表；statement = IS | BS | CF）
 * 缺值輸出 n/a（絕不是 0）。UTF-8 BOM 讓 Excel 正確讀中文。
 */
export default defineEventHandler(async (event) => {
  const query = getQuery(event)
  const ticker = parseTickers(query.ticker)[0]
  const range = parseRange(query as Record<string, unknown>)
  const statement = String(query.statement ?? 'IS').toUpperCase()
  if (!['IS', 'BS', 'CF'].includes(statement)) {
    throw createError({ statusCode: 400, statusMessage: 'Bad Request', message: 'statement 須為 IS、BS 或 CF' })
  }

  const ref = await resolveTicker(ticker)
  if (!ref) {
    throw createError({ statusCode: 404, statusMessage: 'Not Found', message: `找不到「${ticker}」` })
  }
  const fin = clampPeriods(await getFinancials(ref, range.fromFy, range.toFy), range)

  const esc = (s: string) => (/[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s)
  const header = ['科目', 'Line Item', ...fin.periods].map(esc).join(',')
  const rows = fin.lineItems
    .filter((li) => li.statement === statement)
    .map((li) =>
      [
        esc(li.zh),
        esc(li.en),
        ...fin.periods.map((p) => {
          const c = li.values[p]
          return c?.value == null ? 'n/a' : String(c.value)
        }),
      ].join(','),
    )

  setHeader(event, 'Content-Type', 'text/csv; charset=utf-8')
  setHeader(
    event,
    'Content-Disposition',
    `attachment; filename="${ref.ticker}_${statement}_${fin.periods[0] ?? ''}-${fin.periods.at(-1) ?? ''}.csv"`.replace(/\s/g, ''),
  )
  return '﻿' + [header, ...rows].join('\r\n')
})

import { defineEventHandler, getQuery, createError, sendRedirect, setHeader } from 'h3'
import { resolveTicker } from '../../utils/cik'
import { getFinancials, loadMap } from '../../utils/financials'
import { parseTickers, parseRange, clampPeriods } from '../../utils/params'

/**
 * GET /api/financials/excel?ticker=AAPL&from=2021Q1&to=2026Q2
 *
 * 快取 key：{ticker}_{from}_{to}_{mapVersion}（mapVersion 變更自動失效舊檔）。
 * 流程：R2 已有 → 直接 302 到 R2 URL（Cloud Run 不被喚醒）；
 *       沒有 → 呼叫 Cloud Run excel-service 生成並上傳 R2，再 302。
 * 本 route 不落地任何檔案。
 */
export default defineEventHandler(async (event) => {
  const query = getQuery(event)
  const ticker = parseTickers(query.ticker)[0]
  const range = parseRange(query as Record<string, unknown>)

  const serviceUrl = process.env.EXCEL_SERVICE_URL
  if (!serviceUrl) {
    throw createError({
      statusCode: 503,
      statusMessage: 'Service Unavailable',
      message: 'Excel 服務尚未設定（EXCEL_SERVICE_URL）',
    })
  }

  const ref = await resolveTicker(ticker)
  if (!ref) {
    throw createError({ statusCode: 404, statusMessage: 'Not Found', message: `找不到「${ticker}」` })
  }

  const mapVersion = (await loadMap()).version
  const from = `${range.fromFy}Q${range.fromQ}`
  const to = `${range.toFy}Q${range.toQ}`
  const cacheKey = `${ref.ticker}_${from}_${to}_${mapVersion}.xlsx`

  // R2 命中判斷（單純的檔案存在性檢查，不是快取系統）
  const r2Base = process.env.R2_PUBLIC_BASE_URL
  if (r2Base) {
    const head = await fetch(`${r2Base}/${cacheKey}`, { method: 'HEAD' })
    if (head.ok) return sendRedirect(event, `${r2Base}/${cacheKey}`, 302)
  }

  // 未命中 → 轉呼叫 Cloud Run：資料在此準備好，excel-service 不碰 SEC
  const fin = clampPeriods(await getFinancials(ref, range.fromFy, range.toFy), range)
  const res = await fetch(`${serviceUrl}/generate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ cacheKey, financials: fin, from, to }),
  })
  if (!res.ok) {
    throw createError({
      statusCode: 502,
      statusMessage: 'Bad Gateway',
      message: `Excel 生成失敗（${res.status}）`,
    })
  }
  const ct = res.headers.get('content-type') ?? ''
  if (ct.includes('json')) {
    const { url } = (await res.json()) as { url: string }
    return sendRedirect(event, url, 302)
  }
  // R2 未設定（本地開發）：excel-service 直接串流 .xlsx，原樣轉傳
  setHeader(event, 'Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
  setHeader(event, 'Content-Disposition', `attachment; filename="${cacheKey}"`)
  return new Uint8Array(await res.arrayBuffer())
})

import { defineEventHandler, setHeader } from 'h3'
import { readFileSync, existsSync } from 'node:fs'
import { resolve } from 'node:path'

const SITE = process.env.SITE_URL || 'https://bamhi-financials.example.com'

export default defineEventHandler((event) => {
  let tickers: string[] = ['NVDA', 'AAPL', 'TSLA', 'MSFT', 'AMZN', 'GOOGL', 'META', 'AMD', 'TSM', 'PLTR']
  const p = resolve(process.cwd(), '.static-tickers.json')
  if (existsSync(p)) {
    try {
      tickers = JSON.parse(readFileSync(p, 'utf-8'))
    } catch { /* fallback */ }
  }
  const urls = ['/', ...tickers.map((t) => `/stock/${t}`)]
    .map((u) => `  <url><loc>${SITE}${u}</loc></url>`)
    .join('\n')
  setHeader(event, 'Content-Type', 'application/xml')
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>`
})

import { secFetchJson } from './secFetch'

/**
 * ticker ↔ CIK 雙向對照。
 * 來源：https://www.sec.gov/files/company_tickers.json（24h 記憶體快取）
 * - CIK 補零至 10 位（data.sec.gov 路徑用）
 * - 同一 CIK 多 ticker（GOOG/GOOGL）：byTicker 每個 ticker 各有一筆；byCik 保留全部 ticker
 * - BRK.A 等特殊字元：SEC 檔案內寫成 BRK-A，查詢時 '.' 與 '-' 互轉
 */

interface SecTickerRow { cik_str: number; ticker: string; title: string }

export interface CompanyRef {
  cik: number
  cik10: string
  ticker: string
  tickers: string[]
  name: string
}

let byTicker: Map<string, CompanyRef> | null = null
let loadedAt = 0
const TTL = 24 * 3600 * 1000

export function pad10(cik: number): string {
  return String(cik).padStart(10, '0')
}

async function load(): Promise<Map<string, CompanyRef>> {
  if (byTicker && Date.now() - loadedAt < TTL) return byTicker
  const raw = await secFetchJson<Record<string, SecTickerRow>>(
    'https://www.sec.gov/files/company_tickers.json',
  )
  const rows = Object.values(raw)
  const cikTickers = new Map<number, string[]>()
  for (const r of rows) {
    const list = cikTickers.get(r.cik_str) ?? []
    list.push(r.ticker)
    cikTickers.set(r.cik_str, list)
  }
  const map = new Map<string, CompanyRef>()
  for (const r of rows) {
    map.set(r.ticker.toUpperCase(), {
      cik: r.cik_str,
      cik10: pad10(r.cik_str),
      ticker: r.ticker.toUpperCase(),
      tickers: cikTickers.get(r.cik_str)!,
      name: r.title,
    })
  }
  byTicker = map
  loadedAt = Date.now()
  return map
}

/** 查無回 null（呼叫端負責給明確錯誤訊息，不回空陣列了事） */
export async function resolveTicker(input: string): Promise<CompanyRef | null> {
  const map = await load()
  const t = input.trim().toUpperCase()
  // BRK.A → SEC 檔內為 BRK-A；也接受使用者直接輸入 BRK-A
  return map.get(t) ?? map.get(t.replace(/\./g, '-')) ?? map.get(t.replace(/-/g, '.')) ?? null
}

import { secFetchJson } from './secFetch'
import type { CompanyRef } from './cik'

/**
 * 資料流 A：submissions.json → 財報清單。
 * - filings.recent 只含最近約 1000 筆；目標區間更早時追加抓 filings.files 分頁
 * - 外國發行人（TSM/ASML）：無 10-K/10-Q → 自動改抓 20-F/6-K，isForeignIssuer=true
 * - 10-K/A、10-Q/A 一併列出，isAmendment=true
 * - 季別一律以 reportDate（期末日）為準（NVDA/AAPL 會計年度錯開曆年）
 */

interface RecentBlock {
  form: string[]
  filingDate: string[]
  accessionNumber: string[]
  primaryDocument: string[]
  reportDate: string[]
}

interface Submissions {
  name: string
  entityType?: string
  sicDescription?: string
  fiscalYearEnd?: string // MMDD
  filings: {
    recent: RecentBlock
    files?: { name: string; filingCount: number; filingFrom: string; filingTo: string }[]
  }
}

export interface Filing {
  form: string
  fiscalPeriod: string // 例：FY2026 Q2
  reportDate: string
  filingDate: string
  accessionNumber: string
  url: string
  isAmendment: boolean
}

export interface FilingsResult {
  company: string
  cik: string
  ticker: string
  sic?: string
  fiscalYearEnd?: string
  isForeignIssuer: boolean
  filings: Filing[]
}

const DOMESTIC_FORMS = ['10-K', '10-Q', '10-K/A', '10-Q/A']
const FOREIGN_FORMS = ['20-F', '6-K', '20-F/A', '40-F']

function rowsOf(b: RecentBlock) {
  // SEC 給平行陣列，用 index 對齊組物件
  return b.form.map((form, i) => ({
    form,
    filingDate: b.filingDate[i],
    accessionNumber: b.accessionNumber[i],
    primaryDocument: b.primaryDocument[i],
    reportDate: b.reportDate[i],
  }))
}

/** 文件直連：CIK 不補零、accession 去橫線 */
export function filingUrl(cik: number, accession: string, primaryDocument: string): string {
  return `https://www.sec.gov/Archives/edgar/data/${cik}/${accession.replace(/-/g, '')}/${primaryDocument}`
}

/**
 * 以 reportDate 推季別。fiscalYearEnd 為 MMDD（如 NVDA "0131"）。
 * FY 年 = 期末日落在該會計年度者；Q = 距 FY 年末的月數差推回。
 */
export function fiscalPeriodOf(reportDate: string, fiscalYearEnd: string | undefined, form: string): string {
  if (!reportDate) return ''
  const [y, m] = reportDate.split('-').map(Number)
  const fyeMonth = fiscalYearEnd ? Number(fiscalYearEnd.slice(0, 2)) : 12
  // 期末月距會計年度末的月數（0=年度末季，3=差一季...）
  const diff = (fyeMonth - m + 12) % 12
  // FY 年 = reportDate 往後推 diff 個月落到的年份
  const fy = new Date(y, m - 1 + diff).getFullYear()
  const isAnnual = form.startsWith('10-K') || form.startsWith('20-F') || form.startsWith('40-F')
  if (isAnnual || diff === 0) return `FY${fy}`
  const q = 4 - Math.round(diff / 3)
  return `FY${fy} Q${q}`
}

export async function getFilings(
  ref: CompanyRef,
  fromDate: string,
  toDate: string,
  forms?: string[],
): Promise<FilingsResult> {
  const sub = await secFetchJson<Submissions>(
    `https://data.sec.gov/submissions/CIK${ref.cik10}.json`,
  )

  let rows = rowsOf(sub.filings.recent)

  // Edge case 3：目標區間早於 recent 最舊一筆 → 抓 filings.files 分頁
  const oldestRecent = rows.length ? rows[rows.length - 1].filingDate : ''
  if (sub.filings.files?.length && oldestRecent && fromDate < oldestRecent) {
    for (const f of sub.filings.files) {
      if (f.filingTo >= fromDate) {
        const page = await secFetchJson<RecentBlock>(
          `https://data.sec.gov/submissions/${f.name}`,
        )
        rows = rows.concat(rowsOf(page))
      }
    }
  }

  // Edge case 4：偵測外國發行人（歷史 form type 無 10-K/10-Q 但有 20-F/6-K）
  const allForms = new Set(rows.map((r) => r.form))
  const hasDomestic = DOMESTIC_FORMS.some((f) => allForms.has(f))
  const isForeignIssuer = !hasDomestic && FOREIGN_FORMS.some((f) => allForms.has(f))
  const wanted = forms?.length ? forms : isForeignIssuer ? FOREIGN_FORMS : DOMESTIC_FORMS

  const filings: Filing[] = rows
    .filter((r) => wanted.includes(r.form))
    .filter((r) => {
      const d = r.reportDate || r.filingDate
      return d >= fromDate && d <= toDate
    })
    .map((r) => ({
      form: r.form,
      fiscalPeriod: fiscalPeriodOf(r.reportDate, sub.fiscalYearEnd, r.form),
      reportDate: r.reportDate,
      filingDate: r.filingDate,
      accessionNumber: r.accessionNumber,
      url: filingUrl(ref.cik, r.accessionNumber, r.primaryDocument),
      isAmendment: r.form.endsWith('/A'),
    }))
    .sort((a, b) => (a.reportDate < b.reportDate ? 1 : -1))

  return {
    company: sub.name || ref.name,
    cik: ref.cik10,
    ticker: ref.ticker,
    sic: sub.sicDescription,
    fiscalYearEnd: sub.fiscalYearEnd,
    isForeignIssuer,
    filings,
  }
}

import { secFetchJson } from './secFetch'
import type { CompanyRef } from './cik'

/**
 * 資料流 B：companyfacts → 三大報表季度時間序列。
 * - 對每個 concept 依 xbrl_zh_map.json 的 tags 順序找第一個有資料的標籤（fallback）
 * - 同一期間多筆 frame（重編）→ 取 filed 最新
 * - Q4 = FY − Q1 − Q2 − Q3（IS/CF 流量科目），isEstimated 標記；BS 存量科目直接用 FY 期末值
 * - 缺值 = null（前端/Excel 顯示 n/a，絕不是 0）
 */

interface FactPoint {
  start?: string
  end: string
  val: number
  fy: number
  fp: string // Q1 Q2 Q3 FY
  form: string
  filed: string
  frame?: string
}

type FactTags = Record<string, { units: Record<string, FactPoint[]> }>

interface CompanyFacts {
  entityName: string
  facts: { 'us-gaap'?: FactTags; 'ifrs-full'?: FactTags }
}

export interface MapConcept {
  id: string
  zh: string
  en: string
  statement: 'IS' | 'BS' | 'CF'
  unit: string
  sign: string
  note?: string
  derivable?: string
  tags: string[]
  tags_ifrs?: string[]
}

export interface DerivedMetric {
  id: string
  zh: string
  en: string
  group: string
  formula: string
  desc: string
}

export interface XbrlMap {
  version: string
  concepts: MapConcept[]
  derived: DerivedMetric[]
}

export interface CellValue {
  value: number | null
  isEstimated: boolean // Q4 推算
  sourceTag?: string
  accessionOrForm?: string
  filed?: string
  endDate?: string
}

export interface LineItem {
  id: string
  zh: string
  en: string
  statement: string
  unit: string
  sign: string
  sourceTag: string | null
  values: Record<string, CellValue> // key: "FY2026 Q2"
}

export interface FinancialsResult {
  company: string
  cik: string
  ticker: string
  mapVersion: string
  /** quarterly（us-gaap，期別如 FY2026 Q2）或 annual（IFRS 外國發行人，期別如 FY2024） */
  periodicity: 'quarterly' | 'annual'
  /** 數值幣別。IFRS filer 優先取 20-F 的 USD 便利換算，否則為申報幣別（如 TWD） */
  currency: string
  periods: string[] // 由舊到新
  lineItems: LineItem[]
  derived: DerivedMetric[]
}

let cachedMap: XbrlMap | null = null
export async function loadMap(): Promise<XbrlMap> {
  if (cachedMap) return cachedMap
  // nitro serverAssets（nuxt.config serverAssets: config → repo 根層 config/）
  // 打包進 serverless bundle，本地與 Vercel 皆可讀
  const raw = await useStorage('assets:config').getItem('xbrl_zh_map.json')
  cachedMap = (typeof raw === 'string' ? JSON.parse(raw) : raw) as XbrlMap
  if (!cachedMap?.concepts) throw new Error('xbrl_zh_map.json 載入失敗')
  return cachedMap
}

/** "FY2026 Q2" 排序鍵 */
function periodKey(fy: number, q: number): string {
  return `FY${fy} Q${q}`
}

function unitKeyOf(unit: string): string {
  return unit // USD | shares | USD/shares，與 companyfacts units key 一致
}

/** 期間長度（天）— 區分單季（~91）與累計（半年/九月/全年） */
function spanDays(p: FactPoint): number | null {
  if (!p.start) return null
  return (Date.parse(p.end) - Date.parse(p.start)) / 86400_000
}

const isFlow = (c: MapConcept) => c.statement === 'IS' || c.statement === 'CF'

/**
 * ⚠️ companyfacts 的 fy/fp 是「申報件」的年度/期別，不是數據本身的期間
 * （同一季數字會以比較期身分出現在後續多份申報，fy/fp 各不同）。
 * 期別一律由數據自己的 start/end 日期 + 公司會計年度末月份推得。
 */

/** 由 end 日期推 (fy, q)。fyeMonth = 會計年度末月份（1-12）。 */
function fiscalOf(end: string, fyeMonth: number): { fy: number; q: number } {
  const [y, m] = end.split('-').map(Number)
  const diff = (fyeMonth - m + 12) % 12
  const fy = new Date(y, m - 1 + diff).getFullYear()
  const q = 4 - Math.round(diff / 3)
  return { fy, q }
}

/** 從 XBRL 年度期間（span>300 天）的 end 月份取眾數 → 會計年度末月份 */
function inferFyeMonth(gaap: Record<string, { units: Record<string, FactPoint[]> }>): number {
  const count = new Map<number, number>()
  for (const tag of Object.values(gaap)) {
    for (const points of Object.values(tag.units)) {
      for (const p of points) {
        const days = spanDays(p)
        if (days !== null && days > 300 && days < 400) {
          const m = Number(p.end.split('-')[1])
          count.set(m, (count.get(m) ?? 0) + 1)
        }
      }
    }
  }
  let bestM = 12
  let bestN = 0
  for (const [m, n] of count) if (n > bestN) { bestN = n; bestM = m }
  return bestM
}

/**
 * 從單一 tag 的 point 陣列整理出各 fiscal period 的值。
 * key：Q:{fy}:{q}（單季/存量快照）、A:{fy}（全年累計，推 Q4 用）。
 * 同期間多筆（重編）→ filed 最新。
 */
function collect(points: FactPoint[], flow: boolean, fyeMonth: number) {
  const best = new Map<string, FactPoint>()
  const put = (key: string, p: FactPoint) => {
    const prev = best.get(key)
    if (!prev || p.filed > prev.filed) best.set(key, p)
  }
  for (const p of points) {
    if (!p.end) continue
    if (flow) {
      const days = spanDays(p)
      if (days === null) continue
      if (days > 80 && days < 100) {
        const { fy, q } = fiscalOf(p.end, fyeMonth)
        put(`Q:${fy}:${q}`, p)
      } else if (days > 300 && days < 400) {
        put(`A:${fiscalOf(p.end, fyeMonth).fy}`, p)
      }
      // 半年/九月累計不用
    } else {
      // 存量：期末快照
      const { fy, q } = fiscalOf(p.end, fyeMonth)
      put(`Q:${fy}:${q}`, p)
    }
  }
  return best
}

function toCell(p: FactPoint, tag: string, estimated = false): CellValue {
  return {
    value: p.val,
    isEstimated: estimated,
    sourceTag: tag,
    accessionOrForm: p.form,
    filed: p.filed,
    endDate: p.end,
  }
}

export async function getFinancials(
  ref: CompanyRef,
  fromFy: number,
  toFy: number,
): Promise<FinancialsResult> {
  const map = await loadMap()
  const facts = await secFetchJson<CompanyFacts>(
    `https://data.sec.gov/api/xbrl/companyfacts/CIK${ref.cik10}.json`,
  )
  // 國內發行人 → us-gaap 季度模式；IFRS 外國發行人（TSM/ASML）→ ifrs-full 年度模式
  // （20-F 只有年度 XBRL，6-K 不進 companyfacts）
  const gaap = facts.facts['us-gaap']
  const ifrs = facts.facts['ifrs-full']
  const useIfrs = !gaap || (Object.keys(gaap).length < 20 && !!ifrs)
  const ns: FactTags = (useIfrs ? ifrs : gaap) ?? {}
  const fyeMonth = inferFyeMonth(ns)

  // 幣別：優先 USD（20-F 常附便利換算），否則取 namespace 中最常見的幣別
  const currency = useIfrs ? inferCurrency(ns) : 'USD'
  const unitPrefs = (unit: string): string[] => {
    if (unit === 'USD') return ['USD', currency]
    if (unit === 'USD/shares') return ['USD/shares', `${currency}/shares`]
    return [unit]
  }

  const allPeriods = new Set<string>()
  const lineItems: LineItem[] = []

  for (const concept of map.concepts) {
    const flow = isFlow(concept)
    const tags = useIfrs ? (concept.tags_ifrs ?? []) : concept.tags

    // tags 依優先序逐期 fallback：高優先標籤已有的期間不被覆蓋，
    // 缺的期間由後續標籤補（公司中途換標籤時——如 NVDA 營收——單一標籤涵蓋不了全期間）
    let chosenTag: string | null = null
    const best = new Map<string, FactPoint & { _tag: string }>()
    for (const tag of tags) {
      const units = ns[tag]?.units
      const points = unitPrefs(concept.unit).map((u) => units?.[u]).find((p) => p?.length)
      if (!points) continue
      chosenTag ??= tag
      for (const [key, p] of collect(points, flow, fyeMonth)) {
        if (!best.has(key)) best.set(key, { ...p, _tag: tag })
      }
    }

    const values: Record<string, CellValue> = {}
    for (let fy = fromFy; fy <= toFy; fy++) {
      if (useIfrs) {
        // 年度模式：流量取全年累計，存量取年度末快照（Q4 位置）
        const p = best.get(flow ? `A:${fy}` : `Q:${fy}:4`)
        if (p) values[`FY${fy}`] = toCell(p, p._tag)
        continue
      }
      for (const n of [1, 2, 3, 4] as const) {
        const p = best.get(`Q:${fy}:${n}`)
        if (p) values[periodKey(fy, n)] = toCell(p, p._tag)
      }
      if (flow && !values[periodKey(fy, 4)]) {
        // Edge case 2：Q4 通常只有全年累計 → Q4 = FY − Q1 − Q2 − Q3，標記推算
        const annual = best.get(`A:${fy}`)
        const q = [1, 2, 3].map((n) => best.get(`Q:${fy}:${n}`))
        if (annual && q[0] && q[1] && q[2]) {
          values[periodKey(fy, 4)] = {
            value: annual.val - q[0]!.val - q[1]!.val - q[2]!.val,
            isEstimated: true,
            sourceTag: annual._tag,
            accessionOrForm: annual.form,
            filed: annual.filed,
            endDate: annual.end,
          }
        }
      }
    }
    for (const k of Object.keys(values)) allPeriods.add(k)
    lineItems.push({
      id: concept.id,
      zh: concept.zh,
      en: concept.en,
      statement: concept.statement,
      unit: concept.unit,
      sign: concept.sign,
      sourceTag: chosenTag,
      values,
    })
  }

  const periods = [...allPeriods].sort() // FY2023 Q1 < FY2023 Q2 < ...（年度模式 FY2023 < FY2024）字典序即正確
  return {
    company: facts.entityName || ref.name,
    cik: ref.cik10,
    ticker: ref.ticker,
    mapVersion: map.version,
    periodicity: useIfrs ? 'annual' : 'quarterly',
    currency,
    periods,
    lineItems,
    derived: map.derived,
  }
}

/** IFRS namespace 內最常見的幣別 unit key（排除 shares/pure）。有 USD 便利換算就回 USD。 */
function inferCurrency(ns: FactTags): string {
  const count = new Map<string, number>()
  for (const tag of Object.values(ns)) {
    for (const u of Object.keys(tag.units)) {
      if (/^[A-Z]{3}$/.test(u)) count.set(u, (count.get(u) ?? 0) + 1)
    }
  }
  if (count.has('USD')) return 'USD'
  let bestU = 'USD'
  let bestN = 0
  for (const [u, n] of count) if (n > bestN) { bestN = n; bestU = u }
  return bestU
}

import { createError } from 'h3'

/** 查詢參數共用解析。上限：5 檔 ticker、40 季（≈10 年），訊息用友善文案。 */

export const MAX_TICKERS = 5
export const MAX_QUARTERS = 40

export function parseTickers(raw: unknown): string[] {
  const list = String(raw ?? '')
    .split(',')
    .map((t) => t.trim().toUpperCase())
    .filter(Boolean)
  if (!list.length) {
    throw createError({ statusCode: 400, statusMessage: 'Bad Request', message: '請輸入至少一個 ticker' })
  }
  if (list.length > MAX_TICKERS) {
    throw createError({
      statusCode: 400,
      statusMessage: 'Bad Request',
      message: `單次比較上限 ${MAX_TICKERS} 檔，可分批查詢`,
    })
  }
  return list
}

export interface QuarterRange {
  fromFy: number
  fromQ: number
  toFy: number
  toQ: number
  fromDate: string // 概略日期範圍（過濾 reportDate 用）
  toDate: string
  nQuarters: number
}

/** "2021Q1" 之類。years=N 為捷徑（往回 N 年）。 */
export function parseRange(query: Record<string, unknown>): QuarterRange {
  const now = new Date()
  let fromFy: number, fromQ: number, toFy: number, toQ: number

  const qre = /^(\d{4})Q([1-4])$/i
  const from = String(query.from ?? '')
  const to = String(query.to ?? '')
  if (qre.test(from) && qre.test(to)) {
    ;[, fromFy, fromQ] = from.match(qre)!.map(Number) as unknown as [number, number, number]
    ;[, toFy, toQ] = to.match(qre)!.map(Number) as unknown as [number, number, number]
  } else {
    const years = Math.min(Number(query.years ?? 5) || 5, 10)
    toFy = now.getFullYear() + 1 // 會計年度可能超前曆年（NVDA FY2026 在 2025）
    toQ = 4
    fromFy = toFy - years
    fromQ = 1
  }

  const n = (toFy - fromFy) * 4 + (toQ - fromQ) + 1
  if (n <= 0) {
    throw createError({ statusCode: 400, statusMessage: 'Bad Request', message: '起始季度不可晚於結束季度' })
  }
  if (n > MAX_QUARTERS) {
    throw createError({
      statusCode: 400,
      statusMessage: 'Bad Request',
      message: `單次查詢上限 ${MAX_QUARTERS} 季（約 10 年），可分批查詢`,
    })
  }

  // 日期界線放寬一年涵蓋錯開的會計年度
  const fromDate = `${fromFy - 1}-01-01`
  const toDate = `${toFy + 1}-12-31`
  return { fromFy, fromQ, toFy, toQ, fromDate, toDate, nQuarters: n }
}

/** 把 financials 結果裁到 range 的起訖「季度」（getFinancials 只吃整年）。 */
export function clampPeriods<T extends { periods: string[]; lineItems: { values: Record<string, unknown> }[] }>(
  fin: T,
  range: QuarterRange,
): T {
  const lo = range.fromFy * 4 + range.fromQ
  const hi = range.toFy * 4 + range.toQ
  const inRange = (p: string) => {
    const m = p.match(/^FY(\d{4})(?: Q([1-4]))?$/)
    if (!m) return false
    // 年度模式（"FY2024"）視為 Q4 位置
    const idx = Number(m[1]) * 4 + (m[2] ? Number(m[2]) : 4)
    return idx >= lo && idx <= hi
  }
  fin.periods = fin.periods.filter(inRange)
  for (const li of fin.lineItems) {
    li.values = Object.fromEntries(Object.entries(li.values).filter(([k]) => inRange(k)))
  }
  return fin
}

/**
 * SEC 限速模組 — v1：行程內最小間隔。
 * v2 要換 Redis token bucket 時只改這個檔案的實作，上層 secFetch 不動。
 */
const MIN_INTERVAL_MS = 100

let lastAcquired = 0
let queue: Promise<void> = Promise.resolve()

export const rateLimiter = {
  acquire(): Promise<void> {
    queue = queue.then(async () => {
      const now = Date.now()
      const wait = lastAcquired + MIN_INTERVAL_MS - now
      if (wait > 0) await new Promise((r) => setTimeout(r, wait))
      lastAcquired = Date.now()
    })
    return queue
  },
}

import { rateLimiter } from './rateLimiter'

/**
 * 所有對 sec.gov / data.sec.gov 的請求唯一入口。
 * - 必帶 User-Agent（SEC 合規，缺了會 403 並可能封 IP）
 * - rateLimiter.acquire() 控制最小間隔
 * - 429 指數退避（最多 3 次重試）
 * - 行程內回應快取：已提交的財報不可變，company_tickers / submissions 給 24h TTL
 */

const RETRY_MAX = 3
const cache = new Map<string, { at: number; ttl: number; data: unknown }>()

function userAgent(): string {
  // 預設為營運者聯絡方式（SEC 合規要求）；部署環境可用 SEC_USER_AGENT 覆蓋
  return process.env.SEC_USER_AGENT || 'BamHI frank940702@gmail.com'
}

export async function secFetchJson<T>(url: string, ttlMs = 24 * 3600 * 1000): Promise<T> {
  const hit = cache.get(url)
  if (hit && Date.now() - hit.at < hit.ttl) return hit.data as T

  for (let attempt = 0; ; attempt++) {
    await rateLimiter.acquire()
    const res = await fetch(url, {
      headers: { 'User-Agent': userAgent(), 'Accept-Encoding': 'gzip, deflate' },
    })
    if (res.status === 429 && attempt < RETRY_MAX) {
      await new Promise((r) => setTimeout(r, 500 * 2 ** attempt))
      continue
    }
    if (!res.ok) throw new Error(`SEC ${res.status}: ${url}`)
    const data = (await res.json()) as T
    cache.set(url, { at: Date.now(), ttl: ttlMs, data })
    return data
  }
}

